import{_ as i,l as s,o as e,c as l,v as t,p as c,x as r,d as n,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"多核与共享缓存","description":"","frontmatter":{"title":"多核与共享缓存","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/multicore-shared-cache.md","filePath":"cs/multicore-shared-cache.md","lastUpdated":1789023840000}'),p={name:"cs/multicore-shared-cache.md"};function L(m,a,_,u,A,f){const o=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="多核与共享缓存" tabindex="-1">多核与共享缓存 <a class="header-anchor" href="#多核与共享缓存" aria-label="Permalink to &quot;多核与共享缓存&quot;">​</a></h1><div class="epigraph"><p>每个核一套流水线与私有 cache，最后一层再共享；线程级并行不再挤在同一 ROB 里。</p><footer>—— 据 Hennessy and Patterson, Computer Architecture: A Quantitative Approach 整理</footer></div><p><a href="/cs/simd-vector">上一课</a>把规则数据收进一条指令。单核 ILP/DLP 仍受阿姆达尔未并行部分限制，且一块硅上再加宽发射的回报下降。<a href="/cs/coherence-intro">一致性问题引入</a>已经警告多份 cache。<a href="/cs/cpi-amdahl">CPI 与阿姆达尔</a>的对象仍是单处理器时间。本课不重讲 Tomasulo。缺口是：把多个程序计数器放到同一芯片上，用共享内存通信。本课只钉多核与共享末级缓存，协议状态留到 MESI。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一个 ROB 窗口挖不出网页服务器那种任务级并行。复制整台机器则进程间只能走显式消息。缺口是<strong>片上多个核，物理地址同一套，末级 cache 与 DRAM 共享</strong>，从而负载/存储成为核间通信。</p><p>私有 L1 保留命中速度；共享 L2/L3 让核间传递 cache 行比绕到 DRAM 短。没有协议时，上一课引入的一致性问题变成默认情况。</p><p><span class="marginnote">SMT 是同一核多个线程共享执行单元，不是多核。本课先复制核。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每个核：自己的流水线、TLB、L1。片上互连把核接到共享 LLC 与内存控制器。软件看见：线程跑在不同核上，同一虚拟映射（若共享地址空间）或各自页表。本课不写操作系统调度。</p>',9)),(e(),c(h,null,{default:r(()=>[d(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20C0%5B%22%E6%A0%B8%200%20%2B%20L1%22%5D%20--%3E%20LLC%5B%22%E5%85%B1%E4%BA%AB%20LLC%22%5D%0A%20%20C1%5B%22%E6%A0%B8%201%20%2B%20L1%22%5D%20--%3E%20LLC%0A%20%20LLC%20--%3E%20DRAM%5B%22DRAM%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>工作集在 LLC 命中时，核间共享只付片上延迟。私有 L1 仍写回，脏行必须在别的核读之前变成可见——机制是下一课 MESI。本课只要求：共享 LLC 不自动等于 L1 一致。两个核可以跑同一二进制的不同线程，页表可以共享，L1 仍然各持一份。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>并行加速比仍受阿姆达尔约束，现在 \\(f\\) 是可分到多核的那部分。假共享：两个核写同一行的不同字，行在 L1 间弹跳，CPI 出现一致性缺失。布局课会再提；本课承认行是一致性粒度。</p><p><a href="/cs/locality-principle">局部性原理</a>变成每核一套工作集，外加共享结构的工作集。LLC 容量要同时装得下，否则容量缺失变成片外流量。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不画总线事务，不定义 Invalid 与 Shared。不引入 NUMA：内存控制器暂时当作均匀的。存储序（是否允许 store 缓冲对别的核可见乱序）是一致性模型课，不是本课。</p><p>后课默认：片上有多个核、私有 L1、共享 LLC。读别人刚写的变量，必须先有一致性协议。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>多核复制 PC 与 L1，用共享内存和共享 LLC 通信。</li><li>L1 副本使一致性成为常态，不是 DMA 特例。</li><li>MESI 状态机是下一课的缺口。</li><li>SMT 是同核多线程，本课先复制核。</li><li>出处：Hennessy and Patterson, <em>CA:AQA</em> 芯片多处理器。</li></ul>',9))])}const T=i(p,[["render",L]]);export{P as __pageData,T as default};
